<script setup lang="ts">
import { ref, onMounted } from 'vue';
import { ArrowUpRight, ArrowRight, Users, UserPlus, ShieldCheck, Pencil, CircleHelp } from 'lucide-vue-next';
import { useApplication, errorMessage, roleLabel, statusLabel } from '../context';
import type { UserResponse } from '../../../application/dto/responses/user-responses';
const app = useApplication(); const session = app.currentSession();
const users = ref<UserResponse[]>([]); const busy = ref(true); const error = ref('');
const canRead = session?.role === 'ADMIN' || session?.role === 'REVIEWER';
onMounted(async () => { try { if (canRead) users.value = await app.list(); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } });
const initials = (name: string) => name.split(' ').map(s => s[0]).slice(0, 2).join('').toUpperCase();
</script>
<template>
  <div class="page-heading"><div><span class="eyebrow">TU ESPACIO, EN ORDEN</span><h1>Bienvenido a tu panel<span class="heading-dot">.</span></h1><p class="muted">Todo lo que necesitas para gestionar tu equipo, en un solo lugar.</p></div><RouterLink to="/usuarios/crear" class="button primary"><UserPlus :size="18"/>Crear usuario</RouterLink></div>
  <section class="welcome-banner"><div><span class="pill light-pill"><span class="online-dot"/> CONECTADOS PARA CRECER</span><h2>Las personas son el centro.<br>La gestión, ahora más simple.</h2><p>Crea, organiza y acompaña a tu equipo desde un espacio<br class="desktop-break"/> pensado para que todo fluya.</p><RouterLink to="/usuarios" class="banner-link">Explorar usuarios <ArrowRight :size="17"/></RouterLink></div><div class="team-art" aria-hidden="true"><div class="orbit orbit-one"/><div class="orbit orbit-two"/><div class="art-card"><Users :size="35"/><span>Tu equipo</span><strong>En el mismo lugar</strong><div class="art-avatars"><i>JA</i><i>MC</i><i>LV</i><i>+</i></div></div><span class="floating-icon"><ShieldCheck :size="25"/></span><span class="art-spark">✳</span></div></section>
  <div v-if="error" class="error" role="alert">{{ error }}</div>
  <section class="stats-grid"><article class="stat"><div class="stat-label">Total de usuarios<span class="stat-icon"><Users :size="19"/></span></div><strong>{{ busy ? '…' : canRead && !error ? users.length : '—' }}</strong><small>Personas en tu organización</small></article><article class="stat"><div class="stat-label">Usuarios activos<span class="stat-icon mint"><ShieldCheck :size="19"/></span></div><strong>{{ busy ? '…' : canRead && !error ? users.filter(u => u.status === 'ACTIVE').length : '—' }}</strong><small><span class="online-dot"/> Listos para colaborar</small></article><article class="stat"><div class="stat-label">Tu rol de acceso<span class="stat-icon sand"><Pencil :size="18"/></span></div><strong class="role-stat">{{ roleLabel[session?.role || ''] }}</strong><small>Un espacio con el acceso que necesitas</small></article></section>
  <section class="section"><div class="section-heading"><div><h2>¿Qué quieres hacer hoy?</h2><p class="muted">Accesos directos para seguir avanzando.</p></div><span class="section-meta">TU DÍA, MÁS SIMPLE</span></div><div class="actions-grid"><RouterLink to="/usuarios/crear" class="action-card"><span class="action-icon"><UserPlus :size="24"/></span><ArrowUpRight class="corner-arrow" :size="20"/><h3>Haz crecer tu equipo</h3><p>Crea un usuario y dale un lugar<br/>en tu organización.</p><span class="action-link">Crear usuario <ArrowRight :size="15"/></span></RouterLink><RouterLink to="/usuarios" class="action-card"><span class="action-icon cream"><Users :size="24"/></span><ArrowUpRight class="corner-arrow" :size="20"/><h3>Conoce a tu equipo</h3><p>Consulta usuarios, roles y estados.<br/>Toda la información, a mano.</p><span class="action-link">Ver usuarios <ArrowRight :size="15"/></span></RouterLink><RouterLink to="/usuarios/editar" class="action-card"><span class="action-icon lilac"><Pencil :size="23"/></span><ArrowUpRight class="corner-arrow" :size="20"/><h3>Mantén todo al día</h3><p>Actualiza los datos y permisos<br/>de las personas de tu equipo.</p><span class="action-link">Editar usuario <ArrowRight :size="15"/></span></RouterLink></div></section>
  <section class="panel"><div class="panel-heading"><h2>Tu equipo, de un vistazo</h2><RouterLink to="/usuarios" class="text-link">Ver todos <ArrowRight :size="16"/></RouterLink></div><p v-if="busy" class="empty">Cargando usuarios…</p><p v-else-if="!canRead" class="empty">Tu rol de miembro no permite consultar el directorio. Puedes crear usuarios desde el menú.</p><p v-else-if="!users.length" class="empty">{{ error ? 'No se pudo cargar el directorio.' : 'Tu equipo está por comenzar. Crea el primer usuario.' }}</p><div v-else class="table-scroll"><table><thead><tr><th>USUARIO</th><th>ROL</th><th>ESTADO</th><th>DETALLES</th></tr></thead><tbody><tr v-for="user in users.slice(0, 4)" :key="user.id"><td><div class="user-cell"><span class="avatar">{{ initials(user.name) }}</span><div><strong>{{ user.name }}</strong><small>{{ user.email }}</small></div></div></td><td>{{ roleLabel[user.role] }}</td><td><span class="badge" :class="user.status.toLowerCase()"><i/>{{ statusLabel[user.status] }}</span></td><td><RouterLink :to="`/usuarios/${encodeURIComponent(user.id)}/editar`" class="icon-button" :aria-label="`Ver ${user.name}`"><ArrowUpRight :size="18"/></RouterLink></td></tr></tbody></table></div></section>
  <div class="help-strip"><CircleHelp :size="19"/><span>Todo bajo control. Administra los accesos y mantén la información de tu equipo actualizada.</span><ShieldCheck :size="19"/></div>
</template>
